class Solution {
    struct Node {
        long long sum, pref, suff, maxSub;
        Node() : sum(0), pref(0), suff(0), maxSub(-1e18) {}
        Node(long long v) : sum(v), pref(max(0LL, v)), suff(max(0LL, v)), maxSub(v) {}
    };

    int n;
    vector<Node> tree;

    Node merge(const Node& left, const Node& right) {
        Node res;
        res.sum = left.sum + right.sum;
        res.pref = max(left.pref, left.sum + right.pref);
        res.suff = max(right.suff, right.sum + left.suff);
        res.maxSub = max({left.maxSub, right.maxSub, left.suff + right.pref});
        return res;
    }

    void build(const vector<int>& nums, int node, int l, int r) {
        if (l == r) {
            tree[node] = Node(nums[l]);
            return;
        }
        int mid = l + (r - l) / 2;
        build(nums, 2 * node + 1, l, mid);
        build(nums, 2 * node + 2, mid + 1, r);
        tree[node] = merge(tree[2 * node + 1], tree[2 * node + 2]);
    }

    void update(int node, int l, int r, int idx, long long val) {
        if (l == r) {
            tree[node] = Node(val);
            return;
        }
        int mid = l + (r - l) / 2;
        if (idx <= mid) update(2 * node + 1, l, mid, idx, val);
        else update(2 * node + 2, mid + 1, r, idx, val);
        tree[node] = merge(tree[2 * node + 1], tree[2 * node + 2]);
    }

