class Solution {
    static class Node {
        long sum, pref, suff, maxSub;
        Node(long v) {
            this.sum = v;
            this.pref = Math.max(0, v);
            this.suff = Math.max(0, v);
            this.maxSub = v;
        }
    }

    private int n;
    private Node[] tree;

    private Node merge(Node left, Node right) {
        Node res = new Node(0);
        res.sum = left.sum + right.sum;
        res.pref = Math.max(left.pref, left.sum + right.pref);
        res.suff = Math.max(right.suff, right.sum + left.suff);
        res.maxSub = Math.max(Math.max(left.maxSub, right.maxSub), left.suff + right.pref);
        return res;
    }

    private void build(int[] nums, int node, int l, int r) {
        if (l == r) {
            tree[node] = new Node(nums[l]);
            return;
        }
        int mid = (l + r) / 2;
        build(nums, 2 * node + 1, l, mid);
        build(nums, 2 * node + 2, mid + 1, r);
        tree[node] = merge(tree[2 * node + 1], tree[2 * node + 2]);
    }

    private void update(int node, int l, int r, int idx, long val) {
        if (l == r) {
            tree[node] = new Node(val);
            return;
        }
        int mid = (l + r) / 2;
        if (idx <= mid) update(2 * node + 1, l, mid, idx, val);
        else update(2 * node + 2, mid + 1, r, idx, val);
        tree[node] = merge(tree[2 * node + 1], tree[2 * node + 2]);
    }

    public long maxSubarraySum(int[] nums) {
        int maxVal = Integer.MIN_VALUE;
        for (int v : nums) maxVal = Math.max(maxVal, v);
        if (maxVal < 0) return maxVal;

        n = nums.length;
        tree = new Node[4 * n];
        build(nums, 0, 0, n - 1);

        Map<Integer, List<Integer>> map = new HashMap<>();
        for (int i = 0; i < n; ++i) {
            map.computeIfAbsent(nums[i], k -> new ArrayList<>()).add(i);
        }

        long ans = tree[0].maxSub;
        for (Map.Entry<Integer, List<Integer>> entry : map.entrySet()) {
            int v = entry.getKey();
            if (v < 0) {
                List<Integer> indices = entry.getValue();
                for (int idx : indices) update(0, 0, n - 1, idx, 0);
                ans = Math.max(ans, tree[0].maxSub);
                for (int idx : indices) update(0, 0, n - 1, idx, v);
            }
        }
        return ans;
    }
}

var maxSubarraySum = function(nums) {
    let maxVal = -Infinity;
    for (const v of nums) if (v > maxVal) maxVal = v;
    if (maxVal < 0) return maxVal;

    const n = nums.length;
    const sumArr = new Float64Array(4 * n);
    const prefArr = new Float64Array(4 * n);
    const suffArr = new Float64Array(4 * n);
    const maxSubArr = new Float64Array(4 * n);

    function merge(node, lChild, rChild) {
        sumArr[node] = sumArr[lChild] + sumArr[rChild];
        prefArr[node] = Math.max(prefArr[lChild], sumArr[lChild] + prefArr[rChild]);
        suffArr[node] = Math.max(suffArr[rChild], sumArr[rChild] + suffArr[lChild]);
        maxSubArr[node] = Math.max(maxSubArr[lChild], maxSubArr[rChild], suffArr[lChild] + prefArr[rChild]);
    }

    function build(node, l, r) {
        if (l === r) {
            const v = nums[l];
            sumArr[node] = v;
            prefArr[node] = Math.max(0, v);
            suffArr[node] = Math.max(0, v);
            maxSubArr[node] = v;
            return;
        }
        const mid = (l + r) >> 1;
        const lc = 2 * node + 1, rc = 2 * node + 2;
        build(lc, l, mid);
        build(rc, mid + 1, r);
        merge(node, lc, rc);
    }

    function update(node, l, r, idx, val) {
        if (l === r) {
            sumArr[node] = val;
            prefArr[node] = Math.max(0, val);
            suffArr[node] = Math.max(0, val);
            maxSubArr[node] = val;
            return;
        }
        const mid = (l + r) >> 1;
        const lc = 2 * node + 1, rc = 2 * node + 2;
        if (idx <= mid) update(lc, l, mid, idx, val);
        else update(rc, mid + 1, r, idx, val);
        merge(node, lc, rc);
    }

    build(0, 0, n - 1);
    const map = new Map();
    for (let i = 0; i < n; ++i) {
        if (!map.has(nums[i])) map.set(nums[i], []);
        map.get(nums[i]).push(i);
    }

    let ans = maxSubArr[0];
    for (const [v, indices] of map.entries()) {
        if (v < 0) {
            for (const idx of indices) update(0, 0, n - 1, idx, 0);
            if (maxSubArr[0] > ans) ans = maxSubArr[0];
            for (const idx of indices) update(0, 0, n - 1, idx, v);
        }
    }
    return ans;
};
